-- Save MJ: Artifact Types (core SP call only)
DO $mj$
DECLARE
  p_ID_a71ea3d3287d UUID;
  p_Name_a71ea3d3287d VARCHAR(100);
  p_Description_a71ea3d3287d TEXT;
  p_ContentType_a71ea3d3287d VARCHAR(100);
  p_IsEnabled_a71ea3d3287d BOOLEAN;
  p_ParentID_a71ea3d3287d UUID;
  p_ExtractRules_a71ea3d3287d TEXT;
  p_DriverClass_a71ea3d3287d VARCHAR(255);
  p_Icon_a71ea3d3287d VARCHAR(255);
  p_ContentCategory_a71ea3d3287d VARCHAR(10);
  p_ToolLibraryClass_a71ea3d3287d VARCHAR(100);
  p_Priority_a71ea3d3287d INTEGER;
  p_DefaultDeliveryMode_a71ea3d3287d VARCHAR(20);
  p_SystemSupplied_a71ea3d3287d BOOLEAN;
BEGIN
  p_ID_a71ea3d3287d := '2E23F219-E790-4A77-9C86-CB19C711B71E';
  p_Name_a71ea3d3287d := 'Video Production';
  p_Description_a71ea3d3287d := 'Production specification, storyboard, style guide, data snapshot, review record, and rendered deliverables manifest for a Video Studio production (VideoGenerationSpec).';
  p_ContentType_a71ea3d3287d := 'application/vnd.mj.video-production+json';
  p_IsEnabled_a71ea3d3287d := TRUE;
  p_ParentID_a71ea3d3287d := (
    SELECT
      "ID"
    FROM
      __mj."ArtifactType"
    WHERE
      LOWER("Name") = LOWER('JSON')
  );
  p_ExtractRules_a71ea3d3287d := '[{"name":"name","description":"Extracts the video production title from Film.OneSentence (truncated to 100 chars), falling back to Archetype.Name or ''Video Production''","type":"string","standardProperty":"name","extractor":"try {\n  const spec = JSON.parse(content);\n  const oneSentence = spec && spec.Film && typeof spec.Film.OneSentence === ''string''\n    ? spec.Film.OneSentence.trim()\n    : '''';\n  if (oneSentence.length > 0) {\n    return oneSentence.slice(0, 100);\n  }\n  const archetypeName = spec && spec.Archetype && typeof spec.Archetype.Name === ''string''\n    ? spec.Archetype.Name.trim()\n    : '''';\n  if (archetypeName.length > 0) {\n    return archetypeName;\n  }\n  return ''Video Production'';\n} catch (_e) {\n  return ''Video Production'';\n}\n"},{"name":"description","description":"Extracts the production purpose from Film.Purpose","type":"string","standardProperty":"description","extractor":"try {\n  const spec = JSON.parse(content);\n  const purpose = spec && spec.Film && typeof spec.Film.Purpose === ''string''\n    ? spec.Film.Purpose.trim()\n    : '''';\n  return purpose.length > 0 ? purpose : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"archetype","description":"Extracts the video archetype name from Archetype.Name","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const archetypeName = spec && spec.Archetype && typeof spec.Archetype.Name === ''string''\n    ? spec.Archetype.Name.trim()\n    : '''';\n  return archetypeName.length > 0 ? archetypeName : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"durationSeconds","description":"Extracts the target runtime in seconds from Film.DurationSeconds","type":"number","extractor":"try {\n  const spec = JSON.parse(content);\n  const duration = spec && spec.Film ? spec.Film.DurationSeconds : undefined;\n  return typeof duration === ''number'' && Number.isFinite(duration) ? duration : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"formats","description":"Extracts the target aspect ratio formats from Film.Formats","type":"Array<string>","extractor":"try {\n  const spec = JSON.parse(content);\n  const formats = spec && spec.Film && Array.isArray(spec.Film.Formats)\n    ? spec.Film.Formats.filter(function (f) { return typeof f === ''string'' && f.trim().length > 0; })\n    : [];\n  return formats;\n} catch (_e) {\n  return [];\n}\n"},{"name":"asOf","description":"Extracts the frozen data snapshot timestamp from DataSnapshot.AsOf","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const asOf = spec && spec.DataSnapshot && typeof spec.DataSnapshot.AsOf === ''string''\n    ? spec.DataSnapshot.AsOf.trim()\n    : '''';\n  return asOf.length > 0 ? asOf : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"displayMarkdown","description":"Builds a markdown summary of the VideoGenerationSpec including one-sentence heading, archetype, duration, formats, status, data as-of timestamp, and generated asset count","type":"string","standardProperty":"displayMarkdown","extractor":"try {\n  const spec = JSON.parse(content);\n  if (!spec || typeof spec !== ''object'') {\n    return null;\n  }\n\n  const oneSentence = spec.Film && typeof spec.Film.OneSentence === ''string'' && spec.Film.OneSentence.trim().length > 0\n    ? spec.Film.OneSentence.trim()\n    : ''Video Production'';\n  const archetype = spec.Archetype && typeof spec.Archetype.Name === ''string'' && spec.Archetype.Name.trim().length > 0\n    ? spec.Archetype.Name.trim()\n    : ''Unspecified'';\n  const duration = spec.Film && typeof spec.Film.DurationSeconds === ''number'' && Number.isFinite(spec.Film.DurationSeconds)\n    ? spec.Film.DurationSeconds + ''s''\n    : ''Unspecified'';\n  const formats = spec.Film && Array.isArray(spec.Film.Formats) && spec.Film.Formats.length > 0\n    ? spec.Film.Formats.join('', '')\n    : ''Unspecified'';\n  const status = typeof spec.Status === ''string'' && spec.Status.trim().length > 0\n    ? spec.Status.trim()\n    : ''Unspecified'';\n\n  const lines = [\n    ''# '' + oneSentence,\n    '''',\n    ''- **Archetype:** '' + archetype,\n    ''- **Duration:** '' + duration,\n    ''- **Formats:** '' + formats,\n    ''- **Status:** '' + status\n  ];\n\n  const asOf = spec.DataSnapshot && typeof spec.DataSnapshot.AsOf === ''string''\n    ? spec.DataSnapshot.AsOf.trim()\n    : '''';\n  if (asOf.length > 0) {\n    lines.push(''- Data as of '' + asOf);\n  }\n\n  const approved = spec.Assets && Array.isArray(spec.Assets.Approved)\n    ? spec.Assets.Approved\n    : [];\n  const generatedCount = approved.filter(function (asset) {\n    return asset && asset.Provenance === ''Generated'';\n  }).length;\n  if (generatedCount > 0) {\n    lines.push(''- Contains AI-generated assets: '' + generatedCount);\n  }\n\n  return lines.join(''\\n'');\n} catch (_e) {\n  return null;\n}\n"},{"name":"posterFileID","description":"Extracts the MJ: Files ID for the rendered poster frame from Output.PosterFileID","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const posterFileId = spec && spec.Output && typeof spec.Output.PosterFileID === ''string''\n    ? spec.Output.PosterFileID.trim()\n    : '''';\n  return posterFileId.length > 0 && !posterFileId.startsWith(''inline:'') ? posterFileId : null;\n} catch (_e) {\n  return null;\n}\n\n"},{"name":"status","description":"Extracts the lifecycle status of the video production from Status","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const status = spec && typeof spec.Status === ''string''\n    ? spec.Status.trim()\n    : '''';\n  return status.length > 0 ? status : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"brandKitID","description":"Extracts the MJ: Brand Kits ID referenced by the video production from BrandKitID","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const brandKitId = spec && typeof spec.BrandKitID === ''string''\n    ? spec.BrandKitID.trim()\n    : '''';\n  return brandKitId.length > 0 ? brandKitId : null;\n} catch (_e) {\n  return null;\n}\n"},{"name":"companyID","description":"Extracts the Company ID associated with the video production from CompanyID","type":"string","extractor":"try {\n  const spec = JSON.parse(content);\n  const companyId = spec && typeof spec.CompanyID === ''string''\n    ? spec.CompanyID.trim()\n    : '''';\n  return companyId.length > 0 ? companyId : null;\n} catch (_e) {\n  return null;\n}\n"}]';
  p_DriverClass_a71ea3d3287d := 'VideoProductionViewerPlugin';
  p_Icon_a71ea3d3287d := 'fa-solid fa-clapperboard';
  p_ContentCategory_a71ea3d3287d := 'Text';
  p_Priority_a71ea3d3287d := 0;
  p_DefaultDeliveryMode_a71ea3d3287d := 'ToolsOnly';
  p_SystemSupplied_a71ea3d3287d := FALSE;
  IF NOT EXISTS (SELECT 1 FROM __mj."ArtifactType" WHERE "ID" = p_ID_a71ea3d3287d) THEN
    IF EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = '__mj' AND p.proname = 'spCreateArtifactType'
         AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
    ) THEN
      PERFORM __mj."spCreateArtifactType"(p_data := jsonb_build_object(
