    'Name', p_Name_a71ea3d3287d,
    'Description', p_Description_a71ea3d3287d,
    'ContentType', p_ContentType_a71ea3d3287d,
    'IsEnabled', p_IsEnabled_a71ea3d3287d,
    'ParentID', p_ParentID_a71ea3d3287d,
    'ExtractRules', p_ExtractRules_a71ea3d3287d,
    'DriverClass', p_DriverClass_a71ea3d3287d,
    'Icon', p_Icon_a71ea3d3287d,
    'ContentCategory', p_ContentCategory_a71ea3d3287d,
    'ToolLibraryClass', p_ToolLibraryClass_a71ea3d3287d,
    'Priority', p_Priority_a71ea3d3287d,
    'DefaultDeliveryMode', p_DefaultDeliveryMode_a71ea3d3287d,
    'SystemSupplied', p_SystemSupplied_a71ea3d3287d
  ));
    ELSE
      PERFORM __mj."spCreateArtifactType"(p_ID := p_ID_a71ea3d3287d, p_Name := p_Name_a71ea3d3287d, p_Description := p_Description_a71ea3d3287d, p_ContentType := p_ContentType_a71ea3d3287d, p_IsEnabled := p_IsEnabled_a71ea3d3287d, p_ParentID := p_ParentID_a71ea3d3287d, p_ExtractRules := p_ExtractRules_a71ea3d3287d, p_DriverClass := p_DriverClass_a71ea3d3287d, p_Icon := p_Icon_a71ea3d3287d, p_ContentCategory := p_ContentCategory_a71ea3d3287d, p_ToolLibraryClass := p_ToolLibraryClass_a71ea3d3287d, p_ToolLibraryClass_Clear := TRUE, p_Priority := p_Priority_a71ea3d3287d, p_DefaultDeliveryMode := p_DefaultDeliveryMode_a71ea3d3287d, p_SystemSupplied := p_SystemSupplied_a71ea3d3287d);
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = '__mj' AND p.proname = 'spUpdateArtifactType'
         AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
    ) THEN
      PERFORM __mj."spUpdateArtifactType"(p_data := jsonb_build_object(
    'ID', p_ID_a71ea3d3287d,
