       WHERE n.nspname = '__mj' AND p.proname = 'spUpdateQuerySQL'
         AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
    ) THEN
      PERFORM __mj."spUpdateQuerySQL"(p_data := jsonb_build_object(
    'ID', p_ID_f5684e04a521,
