    'QueryID', p_QueryID_4d4b8bbcf40e,
    'SQLDialectID', p_SQLDialectID_4d4b8bbcf40e,
    'SQL', p_SQL_4d4b8bbcf40e
  ));
    ELSE
      PERFORM __mj."spCreateQuerySQL"(p_ID := p_ID_4d4b8bbcf40e, p_QueryID := p_QueryID_4d4b8bbcf40e, p_SQLDialectID := p_SQLDialectID_4d4b8bbcf40e, p_SQL := p_SQL_4d4b8bbcf40e);
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = '__mj' AND p.proname = 'spUpdateQuerySQL'
         AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
    ) THEN
      PERFORM __mj."spUpdateQuerySQL"(p_data := jsonb_build_object(
    'ID', p_ID_4d4b8bbcf40e,
