    'SQL', p_SQL_593e5898b865
  ));
    ELSE
      PERFORM __mj."spCreateQuerySQL"(p_ID := p_ID_593e5898b865, p_QueryID := p_QueryID_593e5898b865, p_SQLDialectID := p_SQLDialectID_593e5898b865, p_SQL := p_SQL_593e5898b865);
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = '__mj' AND p.proname = 'spUpdateQuerySQL'
