BEGIN
  p_SQL_ab6ee16a494a := '-- Composed query: Joins Active Users with Recent Entity Changes
-- Demonstrates {{query:"..."}} composition syntax
-- References two reusable queries and combines their data
SELECT
    au.Name AS UserName,
    au.Email,
    au.Type AS UserType,
    COALESCE(rc.ChangeCount, 0) AS RecentChanges,
    rc.LatestChange
FROM
    {{query:"MJ/Demos/Active Users"}} au
    LEFT JOIN {{query:"MJ/Demos/Recent Entity Changes(lookbackDays=''30'')"}} rc
        ON rc.EntityName IN (
            SELECT e.Name
            FROM __mj.vwEntities e
            WHERE e.ID IN (
                SELECT DISTINCT EntityID
                FROM __mj.vwRecordChanges
                WHERE UserID = au.ID
            )
        )
ORDER BY
    COALESCE(rc.ChangeCount, 0) DESC,
    au.Name
';
  p_TechnicalDescription_ab6ee16a494a := 'This query demonstrates MJ query composition by referencing two reusable queries:
1. {{query:"MJ/Demos/Active Users"}} - provides the user base
2. {{query:"MJ/Demos/Recent Entity Changes(lookbackDays=''30'')"}} - provides change metrics with a static 30-day lookback

At execution time, the composition engine resolves these references into CTEs before the SQL is sent to the database.';
  p_UsesTemplate_ab6ee16a494a := TRUE;
  p_ExtractedSQLHash_ab6ee16a494a := 'f2746ebaaa73730578b97608f7c463981874612d568b768da007fbf8079088a6';
  p_ExtractionStatus_ab6ee16a494a := 'OK';
  p_ID_ab6ee16a494a := 'C2162354-AB2F-4244-8659-C5A4E213E9FA';
