       AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
  ) THEN
    PERFORM __mj."spUpdateQuery"(p_data := jsonb_build_object(
    'SQL', p_SQL_ab6ee16a494a,
