    'ExtractedSQLHash', p_ExtractedSQLHash_ab6ee16a494a,
    'ExtractionStatus', p_ExtractionStatus_ab6ee16a494a,
    'ID', p_ID_ab6ee16a494a
  ));
  ELSE
    PERFORM __mj."spUpdateQuery"(p_SQL := p_SQL_ab6ee16a494a, p_TechnicalDescription := p_TechnicalDescription_ab6ee16a494a, p_UsesTemplate := p_UsesTemplate_ab6ee16a494a, p_ExtractedSQLHash := p_ExtractedSQLHash_ab6ee16a494a, p_ExtractionStatus := p_ExtractionStatus_ab6ee16a494a, p_ID := p_ID_ab6ee16a494a);
