-- Save MJ: Query SQLs (core SP call only)
DO $mj$
DECLARE
  p_SQL_c022e474bea9 TEXT;
  p_ID_c022e474bea9 UUID;
BEGIN
  p_SQL_c022e474bea9 := '-- PostgreSQL variant for External Change Detection - Detect Deletions
-- TECHNICAL DEBT: Joining on dynamically generated PrimaryKeyJoin (a concatenated string) prevents
-- the use of indexes on the organic table (ot). For massive tables, this will result in a table scan.
-- A future schema change to separate RecordID parts into native columns is recommended.
SELECT 
    rc.RecordID, MAX(rc.ChangedAt) AS "ChangedAt"
FROM 
    __mj.vwRecordChanges rc
LEFT JOIN 
    {{ SchemaName | sqlIdentifier }}.{{ BaseView | sqlIdentifier }} ot 
    ON 
    rc.RecordID = {{ PrimaryKeyJoin }}
WHERE 
    {{ PrimaryKeyIsNull }}
    AND 
        rc.EntityID = {{ EntityID | sqlString }} 
    AND 
        rc.Type <> ''Delete''
GROUP BY 
    rc.RecordID
HAVING 
    MAX(CASE WHEN rc.Type = ''Delete'' THEN 1 ELSE 0 END) = 0;
';
  p_ID_c022e474bea9 := 'F325DCBE-347F-4F59-9A8A-A18706803C8B';
  IF EXISTS (
    SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = '__mj' AND p.proname = 'spUpdateQuerySQL'
       AND p.pronargs = 1 AND p.proargtypes[0] = 'jsonb'::regtype
  ) THEN
    PERFORM __mj."spUpdateQuerySQL"(p_data := jsonb_build_object(
    'SQL', p_SQL_c022e474bea9,
