    'Category', p_Category_400e7d452a31,
    'Status', p_Status_400e7d452a31,
    'DefaultDurationSeconds', p_DefaultDurationSeconds_400e7d452a31,
    'MinDurationSeconds', p_MinDurationSeconds_400e7d452a31,
    'MaxDurationSeconds', p_MaxDurationSeconds_400e7d452a31,
    'DefaultFormats', p_DefaultFormats_400e7d452a31,
    'BeatTemplate', p_BeatTemplate_400e7d452a31,
    'Pacing', p_Pacing_400e7d452a31,
    'Guidance', p_Guidance_400e7d452a31,
    'DefaultInteractionMode', p_DefaultInteractionMode_400e7d452a31
  ));
    ELSE
